#ifndef STATUS_VIEW_H
#define STATUS_VIEW_H

#include "ui_types.h"
#include <stddef.h>

/* -----------------------------------------------------------------------
 * status_view.h
 * TEAM CODE (owner: Tony - display and user interface) - written by the BJT2 team, not generated by STM32CubeMX.
 * Authors: written by Brendon (integrator) on 29-30 Oct 2026 for Tony's display/UI subsystem (best-ui).
 * BJT2 Sound Modulating Toy — Power Header and Status Footer (best-ui)
 * Subsystem: Display/UI (Tony). Generative AI was used to assist.
 *
 * Builds the text and colours of the two bands that stay on every screen
 * except Debug:
 *   header (top):    battery icon + SoC, TO EMPTY, TO FULL and a tag
 *                    that says what matters most right now
 *   footer (bottom): SD chip, what is recording or playing (or, for 3 s,
 *                    Jack's answer to REC, PLAY or Delete), the effect
 *                    and MUTE
 * Every field has a fixed width, padded with spaces, so new text always
 * covers the old and the firmware never has to blank a field first.
 *
 * No SPI, no HAL: tony_ui.c turns the colours into RGB565, draws the
 * fields and sends only the ones whose text or colour changed.
 * ----------------------------------------------------------------------- */

/* ===================================================================
 * COLOURS
 * Mapped to RGB565 by a table in tony_ui.c (one entry each), so this
 * module stays free of the ILI9341 driver header.
 * =================================================================== */
typedef enum {
    SV_BLACK = 0,
    SV_WHITE,
    SV_LIGHTGREY,
    SV_DARKGREY,
    SV_RED,
    SV_ORANGE,
    SV_YELLOW,
    SV_GREENYELLOW,
    SV_GREEN,
    SV_CYAN,
    SV_MAGENTA,
    SV_COLOUR_COUNT         /* Sentinel — total number of colours          */
} sv_colour_t;

/* ===================================================================
 * FIELD WIDTHS (characters; every text is exactly this long)
 * =================================================================== */
#define SV_TAG_W            15U     /* "SPEAKER LOCKED", size 1           */
#define SV_SOC_W            4U      /* " 80%", "100%", " --%", size 2     */
#define SV_TIME_W           5U      /* "01:15", "--:--", size 2           */
#define SV_CHIP_W           7U      /* "SD BUSY", size 2                  */
#define SV_LINE1_W          24U     /* "REC 0:07 REC03.WAV", size 1       */
#define SV_FX_W             18U     /* "FX PITCH DOWN 100%", size 1       */
#define SV_MUTE_W           4U      /* "MUTE", size 1                     */

#define SV_FILL_MAX         28U     /* Battery icon inside width, pixels  */
#define SV_NAME_MAX         12U     /* 8.3 file name, the most shown      */
#define SV_REC_LEFT_UNKNOWN 0xFFU   /* Recording, time left not known     */

/* ===================================================================
 * HEADER
 * One colour (level_colour) is shared by the SoC text, the icon outline
 * and the fill, first match wins:
 *   speaker locked RED, no valid reading DARKGREY, critical RED,
 *   low YELLOW, otherwise GREENYELLOW
 * The nub is CYAN while charging, else the level colour.
 * =================================================================== */
typedef struct {
    char        tag[SV_TAG_W + 1U];     /* Tag, padded to 15               */
    sv_colour_t tag_colour;
    char        soc[SV_SOC_W + 1U];     /* "%3u%%", or " --%" if invalid   */
    sv_colour_t level_colour;           /* SoC text, outline and fill      */
    uint8_t     fill_px;                /* 0..SV_FILL_MAX, 0 if invalid    */
    sv_colour_t nub_colour;             /* CYAN while charging             */
    char        tte[SV_TIME_W + 1U];    /* Time to empty, "hh:mm"          */
    sv_colour_t tte_colour;             /* WHITE, DARKGREY for --:--       */
    char        ttf[SV_TIME_W + 1U];    /* Time to full, "hh:mm"           */
    sv_colour_t ttf_colour;
} sv_header_t;

/* ===================================================================
 * FOOTER
 * sv_sd_in_t is a HAL-free copy of the fields of Jack's storage status
 * the footer needs (the firmware fills it from StorageStatusMsg_t).
 * =================================================================== */
typedef struct {
    bool        have_status;    /* At least one status has arrived         */
    bool        card_present;
    bool        mounted;
    bool        msc_mode;       /* Card handed to a PC over USB            */
    bool        recording;
    uint8_t     playing;        /* SV_PLAYING_* (Jack's JACK_PLAY_*)       */
    const char *status_text;    /* Jack's wording, e.g. "Card Full"; NULL ok */
    const char *current_name;   /* 8.3 name recorded / played; NULL ok     */
    bool        fx_busy;        /* Jack is writing effect files: the card
                                 * must not be pulled                      */
} sv_sd_in_t;

/* sv_sd_in_t.playing: Jack's JACK_PLAY_* numbers (app_rtos.h), mirrored so
 * this module stays RTOS-free (tony_ui.c checks that they match). */
#define SV_PLAYING_IDLE         0U  /* nothing playing                    */
#define SV_PLAYING_PLAYING      1U  /* sound is playing                   */
#define SV_PLAYING_PAUSED       2U  /* paused, the file closed            */
#define SV_PLAYING_PREPARING    3U  /* the effect file is being made first */

typedef struct {
    char        text[SV_CHIP_W + 1U];   /* Centred in 7, e.g. " SD OK "    */
    sv_colour_t bg;                     /* The chip box                    */
    sv_colour_t fg;                     /* The text                        */
} sv_chip_t;

typedef struct {
    sv_chip_t   chip;
    char        line1[SV_LINE1_W + 1U]; /* Notice, or transport, or blank  */
    sv_colour_t line1_colour;
    char        fx[SV_FX_W + 1U];       /* "FX <NAME>[ 45%| N/A]"          */
    sv_colour_t fx_colour;
    char        mute[SV_MUTE_W + 1U];   /* "MUTE" or four spaces           */
    sv_colour_t mute_colour;
} sv_footer_t;

/**
 * sv_build_header
 * Header fields from the battery part of the UI state.
 *
 * Tag, first match wins:
 *   SPEAKER LOCKED (RED)       speaker_locked
 *   SOC OVERRIDE   (MAGENTA)   battery_soc_override (debug screen)
 *   NO GAUGE       (DARKGREY)  !battery_valid
 *   CHARGER FAULT  (RED)       battery_charger_fault
 *   CHARGING       (CYAN)      battery_charging
 *   CRITICAL       (RED)       battery_critical
 *   LOW BATTERY    (YELLOW)    battery_low
 *   ON USB POWER   (LIGHTGREY) battery_ext_power (power good, not charging)
 *   BATTERY        (LIGHTGREY) otherwise
 * SoC: "%3u%%" of battery_pct, " --%" when the reading is not valid.
 * Fill: (min(SoC,100) * 28 + 50) / 100 pixels, 0 when not valid.
 * Times: ui_format_hhmm(), the same text as the Battery screen; WHITE,
 * or DARKGREY for "--:--" (UI_TIME_UNKNOWN).
 *
 * @param s    UI state (read-only). NULL: out is left as it was.
 * @param out  Filled completely. NULL: nothing happens.
 */
void sv_build_header(const ui_state_t *s, sv_header_t *out);

/**
 * sv_sd_chip
 * The SD chip, built from the status fields, first match wins:
 *   no status yet (NULL in too)   "SD ..."   DARKGREY / WHITE
 *   USB-MSC mode                  "SD USB"   CYAN     / BLACK
 *   recording, playing, paused,   "SD BUSY"  ORANGE   / BLACK (do not pull)
 *   preparing, or effect files
 *   being made (fx_busy)
 *   no card                       "NO SD"    RED      / WHITE
 *   mounted                       "SD OK"    GREEN    / BLACK
 *   text "Card Full"              "SD FULL"  RED      / WHITE
 *   text "Card Not Ready"         "SD WAIT"  YELLOW   / BLACK
 *   anything else                 "SD ERR"   RED      / WHITE
 * Jack's status text only decides for a card that is in but not mounted.
 * The text is centred in exactly SV_CHIP_W characters.
 *
 * @param sd   Storage status, or NULL (= none yet).
 * @param out  Filled completely. NULL: nothing happens.
 */
void sv_sd_chip(const sv_sd_in_t *sd, sv_chip_t *out);

/**
 * sv_build_footer
 * Footer fields. Line 1 (24 columns), first match wins:
 *   notice (not NULL, not "")   the notice   LIGHTGREY when notice_info,
 *                                            else ORANGE (a refusal)
 *   recording                   "REC m:ss <name>"                RED
 *                               "SAVING <name>" when rec_left_s is 0
 *                               "REC <name>" when it is SV_REC_LEFT_UNKNOWN
 *   preparing (ui_is_preparing) "PREPARING <name>"               YELLOW
 *   playing                     "PLAYING <name>"                 GREEN
 *   paused                      "PAUSED <name>"                  YELLOW
 *   idle                        blank
 * The transport state is s->playback (what the Record and Play screens
 * show); <name> is sd->current_name, at most 12 characters.
 * Line 2: the FX field (18 columns), first match wins:
 *   preparing                   "FX <NAME> 45%"   YELLOW   (being made)
 *   fx_na                       "FX <NAME> N/A"   DARKGREY (the original plays)
 *   no effect                   "FX NONE"         DARKGREY
 *   otherwise                   "FX <NAME>"       LIGHTGREY
 * and "MUTE" (RED) only when muted and the speaker is not locked (the tag
 * says SPEAKER LOCKED then). All of it upper case (size-1 text).
 *
 * @param s           UI state (read-only). NULL: out is left as it was.
 * @param sd          Storage status, or NULL (= none yet).
 * @param rec_left_s  Recording time left in seconds (the Record screen's
 *                    countdown), or SV_REC_LEFT_UNKNOWN.
 * @param notice      Text that replaces line 1 for a while, or NULL.
 * @param notice_info true: the notice is information ("DELETED
 *                    REC05.WAV"), shown light grey; false: a refusal,
 *                    shown orange.
 * @param out         Filled completely. NULL: nothing happens.
 */
void sv_build_footer(const ui_state_t *s, const sv_sd_in_t *sd, uint8_t rec_left_s,
                     const char *notice, bool notice_info, sv_footer_t *out);

/* ===================================================================
 * REFUSAL NOTICES
 * Jack refuses RECORD_START or PLAY_START (his ack ok = 0) when the card
 * is missing, on a PC, full, not ready or faulty, or when there is
 * nothing to play. Footer line 1 then says why, for SV_NOTICE_MS.
 * =================================================================== */
#define SV_NOTICE_MS        3000U   /* How long a refusal notice shows    */

/**
 * sv_refusal_text
 * Why Jack refused REC or PLAY, for footer line 1. The rules are the SD
 * chip's, in the same order, so the notice and the chip always agree.
 * First match wins (<CMD> is REC or PLAY):
 *   no status yet (NULL sd too)    "<CMD>: TRY AGAIN"
 *   USB-MSC mode                   "<CMD>: SD CARD ON PC"
 *   recording, playing, paused,    "<CMD>: TRY AGAIN"      (still busy)
 *   preparing or fx_busy
 *   no card                        "<CMD>: NO SD CARD"
 *   mounted, file_count 0          "PLAY: NO RECORDINGS"   (REC: TRY AGAIN)
 *   mounted                        "<CMD>: TRY AGAIN"      (one file failed)
 *   text "Card Full"               "<CMD>: SD CARD FULL"
 *   text "Card Not Ready"          "<CMD>: SD NOT READY"
 *   anything else                  "<CMD>: SD CARD ERROR"
 * Every text is upper case and at most SV_LINE1_W characters; the
 * firmware passes it to sv_build_footer() as the notice.
 *
 * @param record      true: Jack refused RECORD_START; false: PLAY_START.
 * @param sd          Storage status, or NULL (= none yet).
 * @param file_count  Recordings on the card (Jack's status): all of them,
 *                    so a uint16_t (256 files must not read as 0).
 * @return            A constant text, never NULL.
 */
const char *sv_refusal_text(bool record, const sv_sd_in_t *sd, uint16_t file_count);

/* ===================================================================
 * ANSWERS TO REC, PLAY AND DELETE
 * Jack answers RECORD_START and PLAY_START with an ack, and DELETE in his
 * status (cmd_seq, cmd_ok, cmd_detail): a DELETE has no ack, so its
 * answer can never take the place of a PLAY's (the one-deep reply queue).
 * sv_answer_notice() turns an answer into what footer line 1 says for
 * SV_NOTICE_MS, its colour, and whether the no-SD pop-up opens.
 * =================================================================== */
typedef enum {
    SV_CMD_RECORD = 0,      /* RECORD_START                                */
    SV_CMD_PLAY,            /* PLAY_START                                  */
    SV_CMD_DELETE           /* DELETE                                      */
} sv_cmd_t;

/* Why Jack answered as he did: the numbers of JackAckDetail_t in
 * app_rtos.h (this module stays RTOS-free; tony_ui.c checks at build time
 * that the two lists match). */
typedef enum {
    SV_ACK_NONE = 0,        /* nothing to add                              */
    SV_ACK_PREPARING,       /* PLAY accepted: the effect file is made first */
    SV_ACK_NO_FX,           /* PLAY accepted, plays without the effect     */
    SV_ACK_BUSY,            /* refused: recording, USB mode or busy        */
    SV_ACK_NOT_FOUND,       /* refused: no such file (the list changed)    */
    SV_ACK_FAILED           /* refused: a card error, a file Jack cannot
                             * play, a read-only file                      */
} sv_ack_t;

typedef struct {
    char text[SV_LINE1_W + 1U];         /* "" = no notice (an older one ends) */
    bool info;                          /* true: information, LIGHTGREY;
                                         * false: a refusal, ORANGE        */
    bool popup;                         /* the no-SD pop-up opens, with the
                                         * fault beep (REC / PLAY refusals) */
} sv_notice_t;

/**
 * sv_answer_notice
 * What footer line 1 says about Jack's answer, first match wins:
 *   PLAY accepted, NO_FX           "NO FX FOR THIS FILE"   LIGHTGREY
 *   REC or PLAY accepted           ""                      (an older notice ends)
 *   PLAY refused, NOT_FOUND        "PLAY: FILE GONE"       ORANGE (the list
 *                                                          changed: no pop-up)
 *   REC or PLAY refused            sv_refusal_text()       ORANGE, pop-up
 *   DELETE done                    "DELETED <name>"        LIGHTGREY
 *   DELETE refused, NOT_FOUND      "DELETE: FILE GONE"     ORANGE
 *   DELETE refused, BUSY           "DELETE: SD CARD ON PC" on a PC (msc_mode),
 *                                  else "DELETE: SD BUSY"  ORANGE
 *   DELETE refused, anything else  "DELETE: CARD ERROR"    ORANGE
 * A DELETE answer never opens the pop-up. Every text fits SV_LINE1_W.
 *
 * @param cmd         The command answered.
 * @param ok          Jack's ok (1 accepted / done, 0 refused).
 * @param detail      Jack's detail, an sv_ack_t number.
 * @param sd          His newest status (the words follow the SD chip), or NULL.
 * @param file_count  Recordings on the card (his status).
 * @param name        DELETE: the file, cleaned up for the panel (at most
 *                    12 characters are shown); NULL counts as "".
 * @param out         Filled completely. NULL: nothing happens.
 */
void sv_answer_notice(sv_cmd_t cmd, bool ok, uint8_t detail, const sv_sd_in_t *sd,
                      uint16_t file_count, const char *name, sv_notice_t *out);

/**
 * sv_notice_active
 * Whether a notice that ends at until_ms still shows at now_ms (tick
 * counts in ms): true before until_ms, false from until_ms on, also when
 * the 32-bit tick count wraps in between. The answer flips back after
 * 2^31 ms (24.8 days), so the caller drops a notice once it has ended.
 *
 * @param now_ms    The tick count now.
 * @param until_ms  When the notice ends (when it was set + SV_NOTICE_MS).
 * @return          true while the notice shows.
 */
bool sv_notice_active(uint32_t now_ms, uint32_t until_ms);

/**
 * sv_sanitize
 * Makes text from another task safe for the 96-glyph font: every byte
 * outside 0x20..0x7E up to the first NUL becomes '?'. If there is no NUL
 * within len bytes, the last byte becomes one, so the text always ends.
 *
 * @param text  Text to fix in place. NULL: nothing happens.
 * @param len   Size of the buffer. 0: nothing happens.
 */
void sv_sanitize(char *text, size_t len);

#endif /* STATUS_VIEW_H */
